function clearSequence() {
  clearTimeout(revealTimer);
  clearTimeout(resultTimer);
}

function showScreen(name) {
  clearSequence();
  screens.forEach(screen => screen.classList.toggle('is-active', screen.dataset.screen === name));
  if (name === 'reveal') {
    revealScreen.classList.remove('reveal-visible', 'result-visible');
    signatureReveal.setAttribute('aria-hidden', 'true');
    resultStage.setAttribute('aria-hidden', 'true');
    const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduced) showResult();
    else revealTimer = setTimeout(showReveal, 2200);
  }
}

function showReveal() {
  clearSequence();
  revealScreen.classList.add('reveal-visible');
  signatureReveal.setAttribute('aria-hidden', 'false');
  resultTimer = setTimeout(showResult, 2500);
}

function showResult() {
  clearSequence();
  revealScreen.classList.add('reveal-visible', 'result-visible');
  signatureReveal.setAttribute('aria-hidden', 'true');
  resultStage.setAttribute('aria-hidden', 'false');
  resultStage.querySelector('button')?.focus({preventScroll:true});
}

function showToast(key) {
  toast.textContent = toastCopy[locale][key] || '';
  toast.classList.add('is-visible');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove('is-visible'), 2600);
}

function applyLocale(next) {
  if (!copy[next]) return;
  locale = next;
  document.documentElement.lang = locale;
  document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
  document.querySelectorAll('[data-i18n]').forEach(node => {
    const value = copy[locale][node.dataset.i18n];
    if (value) node.innerHTML = value;
  });
  document.querySelectorAll('[data-i18n-aria]').forEach(node => {
    const value = copy[locale][node.dataset.i18nAria];
    if (value) node.setAttribute('aria-label', value);
  });
  localeSelect.value = locale;
  const url = new URL(location.href);
  url.searchParams.set('lang', locale);
  history.replaceState(null, '', url);
}

document.addEventListener('click', event => {
  const target = event.target.closest('button');
  if (!target) return;
  if (target.dataset.next) showScreen(target.dataset.next);
  if (target.dataset.jump) showScreen(target.dataset.jump);
  if (target.hasAttribute('data-show-reveal')) showReveal();
  if (target.hasAttribute('data-show-result')) showResult();
  if (target.dataset.toastKey) showToast(target.dataset.toastKey);
});

localeSelect.addEventListener('change', event => applyLocale(event.target.value));
const requestedLocale = new URL(location.href).searchParams.get('lang');
applyLocale(copy[requestedLocale] ? requestedLocale : 'en');
